#include "ruletok.h"

#include <string.h>

static int is_digit(int c) { return c >= '0' && c <= '9'; }

static int is_alpha(int c) { return (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || c == '_'; }

static int fail(rt_err *e, int code, size_t pos) {
    if (e) {
        e->code = code;
        e->pos = pos;
    }
    return -1;
}

int rt_tokenize(const char *s, size_t n, rt_token *out, size_t max, rt_err *err) {
    size_t i = 0, count = 1;
    while (i < n) {
        char c = s[i];
        rt_token t;
        if (c == ' ' || c == '\t') {
            i++;
            continue;
        }
        t.pos = i;
        t.value = 0;
        if (is_digit(c) || (c == '-' && i + 1 < n && is_digit(s[i + 1]))) {
            size_t j = i;
            int neg = 0;
            long v = 0;
            if (c == '-') {
                neg = 1;
                j++;
            }
            for (; j < n && is_digit(s[j]); j++) {
                v = v * 10 + (s[j] - '0');
                if (v > 100000) return fail(err, RT_E_RANGE, i);
            }
            v *= 10;
            if (j < n && s[j] == '.' && !(j + 1 < n && s[j + 1] == '.')) {
                if (j + 1 >= n || !is_digit(s[j + 1])) return fail(err, RT_E_TOKEN, j);
                v += s[j + 1] - '0';
                j += 2;
                if (j < n && is_digit(s[j])) return fail(err, RT_E_TOKEN, j);
                if (v > 1000000) return fail(err, RT_E_RANGE, i);
            }
            t.kind = RT_NUM;
            t.value = (int32_t)(neg ? -v : v);
            t.len = j - i;
        } else if (is_alpha(c)) {
            size_t j = i;
            while (j < n && (is_alpha(s[j]) || is_digit(s[j]))) j++;
            if (j - i > RT_IDENT_MAX) return fail(err, RT_E_TOKEN, i);
            t.len = j - i;
            t.kind = (t.len == 2 && s[i] == 'i' && s[i + 1] == 'n') ? RT_IN : RT_IDENT;
        } else {
            char d = i + 1 < n ? s[i + 1] : '\0';
            t.len = 1;
            switch (c) {
            case '<': t.kind = d == '=' ? RT_LE : RT_LT; break;
            case '>': t.kind = d == '=' ? RT_GE : RT_GT; break;
            case '=':
                if (d != '=') return fail(err, RT_E_TOKEN, i);
                t.kind = RT_EQ;
                break;
            case '!': t.kind = d == '=' ? RT_NE : RT_NOT; break;
            case '.':
                if (d != '.') return fail(err, RT_E_TOKEN, i);
                t.kind = RT_DOTDOT;
                break;
            case '&': t.kind = RT_AND; break;
            case '|': t.kind = RT_OR; break;
            case '(': t.kind = RT_LPAREN; break;
            case ')': t.kind = RT_RPAREN; break;
            case '[': t.kind = RT_LBRACK; break;
            case ']': t.kind = RT_RBRACK; break;
            default: return fail(err, RT_E_TOKEN, i);
            }
            if (t.kind == RT_LE || t.kind == RT_GE || t.kind == RT_EQ || t.kind == RT_NE || t.kind == RT_DOTDOT) t.len = 2;
        }
        if (count == max) return fail(err, RT_E_TOOMANY, t.pos);
        out[count++] = t;
        i += t.len;
    }
    return (int)count;
}

typedef struct {
    const rt_token *t;
    size_t n, i, src_len;
    const char *src;
    const rt_var *vars;
    size_t nvars;
    rt_err *err;
    int depth;
} parser;

static int peek(const parser *p) { return p->i < p->n ? p->t[p->i].kind : 0; }

static size_t here(const parser *p) { return p->i < p->n ? p->t[p->i].pos : p->src_len; }

static int expect(parser *p, int kind) {
    if (peek(p) != kind) return fail(p->err, RT_E_SYNTAX, here(p));
    p->i++;
    return 0;
}

static int parse_or(parser *p, int32_t *out);

static int descend(parser *p) {
    if (p->depth >= RT_MAX_DEPTH) return fail(p->err, RT_E_DEPTH, here(p));
    p->depth++;
    return 0;
}

static int parse_term(parser *p, int32_t *out) {
    const rt_token *t;
    size_t k;
    switch (peek(p)) {
    case RT_NUM:
        *out = p->t[p->i++].value;
        return 0;
    case RT_IDENT:
        t = &p->t[p->i];
        for (k = 0; k < p->nvars; k++) {
            if (strlen(p->vars[k].name) == t->len && memcmp(p->vars[k].name, p->src + t->pos, t->len) == 0) {
                *out = p->vars[k].value;
                p->i++;
                return 0;
            }
        }
        return fail(p->err, RT_E_VAR, t->pos);
    case RT_LPAREN:
        if (descend(p) < 0) return -1;
        p->i++;
        if (parse_or(p, out) < 0) return -1;
        if (expect(p, RT_RPAREN) < 0) return -1;
        p->depth--;
        return 0;
    default:
        return fail(p->err, RT_E_SYNTAX, here(p));
    }
}

static int parse_cmp(parser *p, int32_t *out) {
    int32_t a, b, hi;
    int kind;
    if (parse_term(p, &a) < 0) return -1;
    kind = peek(p);
    if (kind >= RT_LT && kind <= RT_NE) {
        p->i++;
        if (parse_term(p, &b) < 0) return -1;
        switch (kind) {
        case RT_LT: *out = a < b; break;
        case RT_LE: *out = a <= b; break;
        case RT_GT: *out = a > b; break;
        case RT_GE: *out = a >= b; break;
        case RT_EQ: *out = a == b; break;
        default: *out = a != b; break;
        }
    } else if (kind == RT_IN) {
        p->i++;
        if (expect(p, RT_LBRACK) < 0 || parse_term(p, &b) < 0 || expect(p, RT_DOTDOT) < 0 || parse_term(p, &hi) < 0 ||
            expect(p, RT_RBRACK) < 0)
            return -1;
        *out = a >= b && a <= hi;
    } else {
        *out = a;
    }
    return 0;
}

static int parse_not(parser *p, int32_t *out) {
    if (peek(p) == RT_NOT) {
        int32_t v;
        if (descend(p) < 0) return -1;
        p->i++;
        if (parse_not(p, &v) < 0) return -1;
        p->depth--;
        *out = !v;
        return 0;
    }
    return parse_cmp(p, out);
}

static int parse_and(parser *p, int32_t *out) {
    int32_t v, rhs;
    if (parse_not(p, &v) < 0) return -1;
    if (peek(p) != RT_AND) {
        *out = v;
        return 0;
    }
    v = v != 0;
    while (peek(p) == RT_AND) {
        p->i++;
        if (parse_not(p, &rhs) < 0) return -1;
        v = v && rhs;
    }
    *out = v;
    return 0;
}

static int parse_or(parser *p, int32_t *out) {
    int32_t v, rhs;
    if (parse_and(p, &v) < 0) return -1;
    if (peek(p) != RT_OR) {
        *out = v;
        return 0;
    }
    v = v != 0;
    while (peek(p) == RT_OR) {
        p->i++;
        if (parse_and(p, &rhs) < 0) return -1;
        v = v || rhs;
    }
    *out = v;
    return 0;
}

int rt_eval(const char *src, size_t n, const rt_var *vars, size_t nvars, int32_t *result, rt_err *err) {
    rt_token toks[RT_MAX_TOKENS];
    parser p;
    int32_t v;
    int count = rt_tokenize(src, n, toks, RT_MAX_TOKENS, err);
    if (count < 0) return -1;
    p.t = toks;
    p.n = (size_t)count;
    p.i = 0;
    p.src_len = n;
    p.src = src;
    p.vars = vars;
    p.nvars = nvars;
    p.err = err;
    p.depth = 0;
    if (parse_or(&p, &v) < 0) return -1;
    if (p.i != p.n) return fail(err, RT_E_SYNTAX, here(&p));
    *result = v;
    return 0;
}

start.tests/harness.h:
/* Tiny test harness: every failed CHECK prints one FAIL line; main() ends with `return h_report();`. */
#ifndef HARNESS_H
#define HARNESS_H

#include <signal.h>
#include <stdio.h>
#include <string.h>
#include <unistd.h>

static int h_checks = 0, h_fails = 0;

static void h_on_alarm(int sig) {
    static const char msg[] = "FAIL: the test run timed out (probable infinite loop)\n";
    (void)sig;
    if (write(1, msg, sizeof msg - 1) < 0) { /* nothing to do */ }
    _exit(3);
}

static void h_init(void) {
    setvbuf(stdout, NULL, _IONBF, 0);
    signal(SIGALRM, h_on_alarm);
    alarm(20);
}

#define CHECK(cond) do { \
    h_checks++; \
    if (!(cond)) { h_fails++; printf("FAIL %s:%d: check failed: %s\n", __FILE__, __LINE__, #cond); } \
} while (0)

#define CHECK_INT(got, want) do { \
    long long g_ = (long long)(got), w_ = (long long)(want); \
    h_checks++; \
    if (g_ != w_) { h_fails++; printf("FAIL %s:%d: %s: got %lld, want %lld\n", __FILE__, __LINE__, #got, g_, w_); } \
} while (0)

/* like CHECK_INT / CHECK_STR, but `ctx` (a string, e.g. the input of a table row) is part of the message */
#define CHECK_INT_CTX(ctx, got, want) do { \
    long long g_ = (long long)(got), w_ = (long long)(want); \
    h_checks++; \
    if (g_ != w_) { h_fails++; printf("FAIL %s:%d: [%s] %s: got %lld, want %lld\n", __FILE__, __LINE__, (ctx), #got, g_, w_); } \
} while (0)

#define CHECK_STR_CTX(ctx, got, want) do { \
    const char *g_ = (got), *w_ = (want); \
    h_checks++; \
    if (g_ == NULL || strcmp(g_, w_) != 0) { \
        h_fails++; printf("FAIL %s:%d: [%s] %s: got \"%s\", want \"%s\"\n", __FILE__, __LINE__, (ctx), #got, g_ ? g_ : "(null)", w_); } \
} while (0)

#define CHECK_UINT(got, want) do { \
    unsigned long long g_ = (unsigned long long)(got), w_ = (unsigned long long)(want); \
    h_checks++; \
    if (g_ != w_) { h_fails++; printf("FAIL %s:%d: %s: got %llu (0x%llx), want %llu (0x%llx)\n", __FILE__, __LINE__, #got, g_, g_, w_, w_); } \
} while (0)

#define CHECK_STR(got, want) do { \
    const char *g_ = (got), *w_ = (want); \
    h_checks++; \
    if (g_ == NULL || strcmp(g_, w_) != 0) { \
        h_fails++; printf("FAIL %s:%d: %s: got \"%s\", want \"%s\"\n", __FILE__, __LINE__, #got, g_ ? g_ : "(null)", w_); } \
} while (0)

#define CHECK_MEM(got, want, n) do { \
    const unsigned char *g_ = (const unsigned char *)(got), *w_ = (const unsigned char *)(want); \
    size_t n_ = (size_t)(n), i_; \
    h_checks++; \
    if (memcmp(g_, w_, n_) != 0) { \
        h_fails++; printf("FAIL %s:%d: %s: bytes differ\n  got ", __FILE__, __LINE__, #got); \
        for (i_ = 0; i_ < n_; i_++) printf("%02x", g_[i_]); \
        printf("\n  want "); \
        for (i_ = 0; i_ < n_; i_++) printf("%02x", w_[i_]); \
        printf("\n"); } \
} while (0)

static int h_report(void) {
    printf("%d checks, %d failed\n", h_checks, h_fails);
    return h_fails ? 1 : 0;
}

#endif

