static int parse_term(parser *p, int32_t *out) {
    const rt_token *t;
    size_t k;
    switch (peek(p)) {
    case RT_NUM:
        *out = p->t[p->i++].value;
        return 0;
    case RT_IDENT:
        t = &p->t[p->i];
        for (k = 0; k < p->nvars; k++) {
