#include "harness.h"
#include "ruletok.h"

int main(void) {
    static const char rule[] = "temp >= 30.5 & !vent_open";
    rt_var vars[] = {{"temp", 312}, {"vent_open", 0}};
    int32_t res = -1;
    rt_err err;
    h_init();

    CHECK_INT(rt_eval(rule, sizeof rule - 1, vars, 2, &res, &err), 0);
    CHECK_INT(res, 1);
    CHECK_INT(rt_eval("temp >", 6, vars, 2, &res, &err), -1);
    CHECK_INT(err.code, RT_E_SYNTAX);
    return h_report();
}

